foreach ($f in $files) {
    $targetFile = Join-Path $root $f.RelPath
    $targetDir  = Split-Path $targetFile -Parent

    Write-Host "Creating directory: $targetDir" -ForegroundColor Cyan
    New-Item -ItemType Directory -Force -Path $targetDir | Out-Null

    Write-Host "Decoding and writing: $targetFile" -ForegroundColor Cyan
    $bytes = [System.Convert]::FromBase64String($f.B64)
    [System.IO.File]::WriteAllBytes($targetFile, $bytes)

    if (Test-Path -Path $targetFile) {
        $lineCount = (Get-Content -Path $targetFile).Count
        Write-Host "  OK ($lineCount lines)" -ForegroundColor Green
    } else {
        Write-Host "  FAILED: file was not created." -ForegroundColor Red
        exit 1
    }
}

